{
  "sop_id": "SOP-013",
  "title": "Bill of Quantities (BOQ) Review",
  "steps": [
    {"step_id": "S1", "name": "Create and assign ticket", "role": "Executor", "type": "intake"},
    {"step_id": "S2", "name": "Check BOQ template checklist", "role": "Executor", "type": "work"},
    {"step_id": "S3", "name": "Check quantities and rates", "role": "Executor", "type": "work"},
    {"step_id": "S4", "name": "Summarize variance and submit", "role": "Executor", "type": "work"},
    {"step_id": "A1", "name": "Incharge approval", "role": "Incharge", "type": "approval"},
    {"step_id": "R1", "name": "Rework on rejection", "role": "Executor", "type": "rework"},
    {"step_id": "D1", "name": "Wait for drawings confirmation", "role": "Executor", "type": "decision"},
    {"step_id": "A2", "name": "Lead approval (exceptions only)", "role": "Lead", "type": "approval"}
  ],
  "approvals": [
    {"stage": "Incharge", "condition": "always", "evidence": "The Incharge does not decide until D1 is confirmed."},
    {"stage": "Lead", "condition": "exceptions only", "evidence": "See YAML `exceptions`."}
  ],
  "dependencies": [
    {"dep_id": "D1", "provider": "Operations", "item": "drawings revision or take-off confirmation", "parallel_group": "P1", "evidence": "After submission, if the drawings revision or take-off is not yet confirmed by Operations, log `DependencyWait` (D1)."}
  ],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.9
}
